1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
4	import { KEYS } from '../config/assetManifest';
5	import { t } from '../i18n/strings';
6	import { createButton } from '../ui/Button';
7	import { AudioManager } from '../systems/AudioManager';
8	import { ENV } from '../config/env';
9	import { playSfx, playMusic, Sfx, Music } from '../systems/audio';
10	import { PROMO_COPY_FADE_MS } from '../config/gameConfig';
11	
12	/**
13	 * MenuScene — title, Play (→ Game), and a persisted mute toggle. Fires no
14	 * analytics (start_game fires when the run actually begins, in GameScene).
15	 */
16	export class MenuScene extends Phaser.Scene {
17	  constructor() {
18	    super({ key: SceneKey.Menu });
19	  }
20	
21	  create(): void {
22	    const cx = GAME_WIDTH / 2;
23	
24	    // Drive the browser tab title from i18n (single localized source for the
25	    // game name). The on-canvas title is the `ui_title_logo` asset — we do NOT
26	    // draw `menu_title` over the logo (that would overlap the placeholder).
27	    document.title = t('menu_title');
28	
29	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.screen_bg_menu);
30	    this.add.image(cx, 180, KEYS.ui_title_logo);
31	
32	    this.add
33	      .text(cx, 330, t('menu_subtitle'), {
34	        fontFamily: 'system-ui, sans-serif',
35	        fontSize: '24px',
36	        color: '#3a444d',
37	      })
38	      .setOrigin(0.5);
39	
40	    createButton(this, {
41	      x: cx,
42	      y: 450,
43	      texture: KEYS.ui_btn_play,
44	      label: t('menu_play'),
45	      onClick: () => {
46	        playSfx(this, Sfx.ui);
47	        this.scene.start(SceneKey.Game);
48	      },
49	    });
50	
51	    this.add
52	      .text(cx, 550, t('menu_hint'), {
53	        fontFamily: 'system-ui, sans-serif',
54	        fontSize: '20px',
55	        color: '#3a444d',
56	      })
57	      .setOrigin(0.5);
58	
59	    // Promo teaser chip — the same code the results CTA rewards (spec §6.4) (tap-to-copy).
60	    this.buildPromoCopyChip(cx, 648);
61	
62	    this.buildMuteToggle();
63	
64	    // Menu loop music. Honors the persisted mute (global sound.mute) and the iOS
65	    // unlock installed in BootScene; on first load it plays once the user taps.
66	    playMusic(this, Music.menu);
67	  }
68	
69	  private buildMuteToggle(): void {
70	    const muteBtn = this.add
71	      .image(GAME_WIDTH - 52, 52, this.muteTexture())
72	      .setInteractive({ useHandCursor: true });
73	
74	    const label = this.add
75	      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
76	        fontFamily: 'system-ui, sans-serif',
77	        fontSize: '14px',
78	        color: '#9fb0bd',
79	      })
80	      .setOrigin(0.5, 0);
81	
82	    muteBtn.on(Phaser.Input.Events.POINTER_UP, () => {
83	      AudioManager.toggle(this.sound);
84	      muteBtn.setTexture(this.muteTexture());
85	      label.setText(this.muteLabel());
86	      playSfx(this, Sfx.ui);
87	    });
88	  }
89	
90	  private muteTexture(): string {
91	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
92	  }
93	
94	  private muteLabel(): string {
95	    return AudioManager.isMuted() ? t('menu_sound_off') : t('menu_sound_on');
96	  }
97	
98	  private buildPromoCopyChip(x: number, y: number): void {
99	    const container = this.add.container(x, y);
100	    const chip = this.add.image(0, 0, KEYS.ui_promo_chip).setOrigin(0.5);
101	    const text = this.add
102	      .text(0, 0, `${t('results_promo_label')} ${ENV.promoCode}`, {
103	        fontFamily: 'monospace',
104	        fontSize: '24px',
105	        fontStyle: 'bold',
106	        color: '#20272e',
107	      })
108	      .setOrigin(0.5);
109	    container.add([chip, text]);
110	    container.setSize(400, 100);
111	    container.setInteractive(
112	      new Phaser.Geom.Rectangle(-200, -50, 400, 100),
113	      Phaser.Geom.Rectangle.Contains,
114	    );
115	    if (container.input) container.input.cursor = 'pointer';
116	    container.on(Phaser.Input.Events.POINTER_UP, () => this.copyPromoCode());
117	  }
118	
119	  private async copyPromoCode(): Promise<void> {
120	    try {
121	      if (!navigator.clipboard) {
122	        return; // feature unavailable, silent no-op
123	      }
124	      await navigator.clipboard.writeText(ENV.promoCode);
125	      playSfx(this, Sfx.ui);
126	      this.showCopyConfirmation();
127	    } catch {
128	      // copy failed (e.g., no permission), silent no-op
129	      return;
130	    }
131	  }
132	
133	  private showCopyConfirmation(): void {
134	    const cx = GAME_WIDTH / 2;
135	    const label = this.add
136	      .text(cx, 705, t('results_promo_copied'), {
137	        fontFamily: 'system-ui, sans-serif',
138	        fontSize: '14px',
139	        fontStyle: 'bold',
140	        color: '#6cc04a',
141	      })
142	      .setOrigin(0.5)
143	      .setAlpha(1);
144	    this.tweens.add({
145	      targets: label,
146	      alpha: 0,
147	      duration: PROMO_COPY_FADE_MS,
148	      ease: 'Quad.in',
149	      onComplete: () => label.destroy(),
150	    });
151	  }
152	}
