135	        fontStyle: 'bold',
136	        color: '#6cc04a',
137	      })
138	      .setOrigin(0.5)
139	      .setAlpha(1);
140	    this.tweens.add({
141	      targets: label,
142	      alpha: 0,
143	      duration: PROMO_COPY_FADE_MS,
144	      ease: 'Quad.in',
145	      onComplete: () => label.destroy(),
146	    });
147	  }
148	
149	  private onBuy(): void {
150	    playSfx(this, Sfx.ui);
151	    track('click_buy', { destination: buyDestination(), promo_code: ENV.promoCode });
152	    window.open(buildBuyUrl(), '_blank', 'noopener');
153	  }
