/**
 * enlargeHitArea — give a single Image (typically a small icon button) a CENTERED
 * square hit area of at least `size` logical px, so it clears the comfortable
 * tap-target guideline even after the 1280×720 canvas is FIT-scaled down on a
 * phone. The rectangle is expressed in the texture's local space (origin at the
 * frame's top-left, which is what Phaser's hit test expects) and stays centered
 * on the icon regardless of the image's display origin. Idempotent — safe to call
 * again to re-enable interactivity after `disableInteractive()`.
 */
export function enlargeHitArea(image: Phaser.GameObjects.Image, size = MIN_TAP_TARGET_PX): void {
  const w = Math.max(image.width, size);
  const h = Math.max(image.height, size);
  image.setInteractive(
    new Phaser.Geom.Rectangle((image.width - w) / 2, (image.height - h) / 2, w, h),
    Phaser.Geom.Rectangle.Contains,
  );
  if (image.input) image.input.cursor = 'pointer';
}

