// The hit area is the VISIBLE art, expanded to a comfortable minimum tap target
// on each axis (never smaller). The SVG is rasterized to its manifest size, so
// bg.width/height == the displayed frame; the art fills that frame (only a few
// px of transparent padding), so a frame-sized-or-larger rect covers the whole
// visible button. The rect is in the container's local space and Phaser applies
// the container transform during hit-testing, so the press/hover SCALE never
// shifts the effective hit region off the button.
const hitW = Math.max(width, MIN_TAP_TARGET_PX);
const hitH = Math.max(height, MIN_TAP_TARGET_PX);
container.setSize(hitW, hitH);
container.setInteractive(
  new Phaser.Geom.Rectangle(-hitW / 2, -hitH / 2, hitW, hitH),
  Phaser.Geom.Rectangle.Contains,
);
if (container.input) {
  container.input.cursor = 'pointer';
}

container.on(Phaser.Input.Events.POINTER_OVER, () => container.setScale(HOVER_SCALE));
container.on(Phaser.Input.Events.POINTER_OUT, () => container.setScale(1));
container.on(Phaser.Input.Events.POINTER_DOWN, () => container.setScale(PRESS_SCALE));
// Reset to the resting scale on release. On TOUCH there is no POINTER_OUT after
// a tap, so returning to the hover scale would leave the control stuck enlarged
// — snap back to 1; on mouse, keep the hover scale since the cursor is still on
// the button. POINTER_OUT already handles press-then-drag-off (→ scale 1).
container.on(Phaser.Input.Events.POINTER_UP, (pointer: Phaser.Input.Pointer) => {
  container.setScale(pointer.wasTouch ? 1 : HOVER_SCALE);
  opts.onClick();
});

return container;

