1	import Phaser from 'phaser';
2	import { KEYS } from '../config/assetManifest';
3	import { DEPTH, HUD, GAME_WIDTH, MAX_HP } from '../config/gameConfig';
4	import { t } from '../i18n/strings';
5	import { GameEvents, type ArmorState } from '../scenes/gameEvents';
6	import { AudioManager } from '../systems/AudioManager';
7	import { playSfx, Sfx } from '../systems/audio';
8	import { prefersReducedMotion } from '../systems/a11y';
9	
10	export interface HudOptions {
11	  /** Invoked when the pause button is tapped. */
12	  onPause: () => void;
13	}
14	
15	export interface HudSnapshot {
16	  hp: number;
17	  score: number;
18	  progress: number;
19	}
20	
21	/**
22	 * Hud — the persistent in-run overlay (spec §6.2). It is purely a VIEW: it never
23	 * reaches into the run loop, only SUBSCRIBES to the events GameScene emits on
24	 * `scene.events` and re-paints. Hearts (shape+fill), score, a level-progress bar
25	 * (dynamic fill drawn through the frame's transparent window), plus pause + mute
26	 * controls and a small armor tell. Resets on `run:start`, freezes on `run:end`,
27	 * and removes every listener on scene shutdown (no leaks across replays).
28	 */
29	export class Hud {
30	  private readonly scene: Phaser.Scene;
31	  private readonly opts: HudOptions;
32	
33	  private readonly hearts: Phaser.GameObjects.Image[] = [];
34	  private readonly scoreText: Phaser.GameObjects.Text;
35	  private readonly progressFill: Phaser.GameObjects.Rectangle;
36	  private readonly pauseBtn: Phaser.GameObjects.Image;
37	  private readonly muteBtn: Phaser.GameObjects.Image;
38	  private readonly armorIcon: Phaser.GameObjects.Image;
39	
40	  private armorTween: Phaser.Tweens.Tween | undefined;
41	  private readonly progressUsableWidth: number;
42	  private frozen = false;
43	
44	  constructor(scene: Phaser.Scene, opts: HudOptions, initial?: HudSnapshot) {
45	    this.scene = scene;
46	    this.opts = opts;
47	    this.progressUsableWidth = HUD.progressBarWidth - HUD.progressFillInsetX * 2;
48	
49	    // ── Progress bar: frame asset + a dynamic fill drawn on top ──
50	    scene.add.image(GAME_WIDTH / 2, HUD.progressBarY, KEYS.ui_progress_bar).setDepth(DEPTH.hud);
51	    const fillLeft = GAME_WIDTH / 2 - this.progressUsableWidth / 2;
52	    this.progressFill = scene.add
53	      .rectangle(fillLeft, HUD.progressBarY, this.progressUsableWidth, HUD.progressFillHeight, HUD.progressFillColor)
54	      .setOrigin(0, 0.5)
55	      .setDepth(DEPTH.hud);
56	    this.progressFill.scaleX = 0;
57	
58	    // ── Score row ──
59	    scene.add.image(HUD.scoreIconX, HUD.scoreRowY, KEYS.ui_score_icon).setDepth(DEPTH.hud);
60	    this.scoreText = scene.add
61	      .text(HUD.scoreTextX, HUD.scoreRowY, this.scoreLabel(0), {
62	        fontFamily: 'system-ui, sans-serif',
63	        fontSize: HUD.scoreFontSize,
64	        fontStyle: 'bold',
65	        color: HUD.scoreColor,
66	        stroke: HUD.scoreStrokeColor,
67	        strokeThickness: HUD.scoreStrokeThickness,
68	      })
69	      .setOrigin(0, 0.5)
70	      .setDepth(DEPTH.hud);
71	
72	    // ── Hearts ──
73	    for (let i = 0; i < MAX_HP; i++) {
74	      this.hearts.push(
75	        scene.add.image(HUD.heartStartX + i * HUD.heartSpacing, HUD.heartY, KEYS.ui_heart_full).setDepth(DEPTH.hud),
76	      );
77	    }
78	
79	    // ── Small armor tell (hidden until armored) ──
80	    this.armorIcon = scene.add
81	      .image(HUD.armorTellX, HUD.armorTellY, KEYS.armor_pickup)
82	      .setScale(HUD.armorTellScale)
83	      .setDepth(DEPTH.hud)
84	      .setVisible(false);
85	
86	    // ── Controls (mute then pause, top-right) ──
87	    this.muteBtn = scene.add
88	      .image(HUD.muteBtnX, HUD.muteBtnY, this.muteTexture())
89	      .setDepth(DEPTH.hud)
90	      .setInteractive({ useHandCursor: true });
91	    this.muteBtn.on(Phaser.Input.Events.POINTER_UP, this.onMuteTap, this);
92	
93	    this.pauseBtn = scene.add
94	      .image(HUD.pauseBtnX, HUD.pauseBtnY, KEYS.ui_btn_pause)
95	      .setDepth(DEPTH.hud)
96	      .setInteractive({ useHandCursor: true });
97	    this.pauseBtn.on(Phaser.Input.Events.POINTER_UP, this.onPauseTap, this);
98	
99	    if (initial) {
100	      this.setHp(initial.hp);
101	      this.setScore(initial.score);
102	      this.setProgress(initial.progress);
103	    }
104	
105	    // ── Subscriptions ──
106	    const ev = scene.events;
107	    ev.on(GameEvents.hp, this.onHp, this);
108	    ev.on(GameEvents.score, this.onScore, this);
109	    ev.on(GameEvents.progress, this.onProgress, this);
110	    ev.on(GameEvents.armor, this.onArmor, this);
111	    ev.on(GameEvents.runStart, this.onRunStart, this);
112	    ev.on(GameEvents.runEnd, this.onRunEnd, this);
113	    ev.once(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this);
114	  }
115	
116	  /** Re-read the shared mute state and repaint the icon (e.g. after resume). */
117	  syncMute(): void {
118	    this.muteBtn.setTexture(this.muteTexture());
119	  }
120	
121	  destroy(): void {
122	    const ev = this.scene.events;
123	    ev.off(GameEvents.hp, this.onHp, this);
124	    ev.off(GameEvents.score, this.onScore, this);
125	    ev.off(GameEvents.progress, this.onProgress, this);
126	    ev.off(GameEvents.armor, this.onArmor, this);
127	    ev.off(GameEvents.runStart, this.onRunStart, this);
128	    ev.off(GameEvents.runEnd, this.onRunEnd, this);
129	    ev.off(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this);
130	    this.stopArmorTell();
131	    // Display objects are scene-owned and auto-destroyed on shutdown.
132	  }
133	
134	  // ── Event handlers ──────────────────────────────────────────────────────────
135	  private onHp(hp: number): void {
136	    if (this.frozen) return;
137	    this.setHp(hp);
138	  }
139	
140	  private onScore(score: number): void {
141	    if (this.frozen) return;
142	    this.setScore(score);
143	  }
144	
145	  private onProgress(progress: number): void {
146	    if (this.frozen) return;
147	    this.setProgress(progress);
148	  }
149	
150	  private onArmor(state: ArmorState): void {
151	    if (this.frozen) return;
152	    if (state.active) this.startArmorTell();
153	    else this.stopArmorTell();
154	  }
155	
156	  private onRunStart(): void {
157	    this.frozen = false;
158	    this.setHp(MAX_HP);
159	    this.setScore(0);
160	    this.setProgress(0);
161	    this.stopArmorTell();
162	    this.pauseBtn.setAlpha(1).setInteractive({ useHandCursor: true });
163	  }
164	
165	  private onRunEnd(): void {
166	    // Freeze the HUD in its final state; pausing is meaningless once the run ends.
167	    this.frozen = true;
168	    this.stopArmorTell();
169	    this.pauseBtn.disableInteractive();
170	    this.pauseBtn.setAlpha(HUD.frozenBtnAlpha);
171	  }
172	
173	  // ── Control taps ─────────────────────────────────────────────────────────────
174	  private onMuteTap(): void {
175	    AudioManager.toggle(this.scene.sound);
176	    this.syncMute();
177	    playSfx(this.scene, Sfx.ui);
178	  }
179	
180	  private onPauseTap(): void {
181	    if (this.frozen) return;
182	    playSfx(this.scene, Sfx.ui);
183	    this.opts.onPause();
184	  }
185	
186	  // ── Painters ─────────────────────────────────────────────────────────────────
187	  private setHp(hp: number): void {
188	    this.hearts.forEach((img, i) => {
189	      img.setTexture(i < hp ? KEYS.ui_heart_full : KEYS.ui_heart_empty);
190	    });
191	  }
192	
193	  private setScore(score: number): void {
194	    this.scoreText.setText(this.scoreLabel(score));
195	  }
196	
197	  private setProgress(progress: number): void {
198	    this.progressFill.scaleX = Phaser.Math.Clamp(progress, 0, 1);
199	  }
200	
201	  private scoreLabel(score: number): string {
202	    return `${t('hud_score')}: ${score}`;
203	  }
204	
205	  private muteTexture(): string {
206	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
207	  }
208	
209	  private startArmorTell(): void {
210	    this.armorIcon.setVisible(true).setScale(HUD.armorTellScale);
211	    // The icon's visibility already conveys "armored"; the pulse is decorative,
212	    // so honor prefers-reduced-motion by leaving it static (§10.4).
213	    if (this.armorTween || prefersReducedMotion()) return;
214	    this.armorTween = this.scene.tweens.add({
215	      targets: this.armorIcon,
216	      scale: { from: HUD.armorTellScale, to: HUD.armorTellPulseScale },
217	      duration: HUD.armorTellPulseMs,
218	      yoyo: true,
219	      repeat: -1,
220	      ease: 'Sine.inOut',
221	    });
222	  }
223	
224	  private stopArmorTell(): void {
225	    this.armorTween?.stop();
226	    this.armorTween = undefined;
227	    this.armorIcon.setVisible(false).setScale(HUD.armorTellScale);
228	  }
229	}
