254	  // ── Per-frame loop ────────────────────────────────────────────────────────────
255	  override update(_time: number, delta: number): void {
256	    if (this.finished || this.paused) return;
257	
258	    const dt = delta / 1000;
259	    this.elapsedMs += delta;
260	
261	    const progress = this.curve.progress(this.distance);
262	    const worldSpeed = this.curve.speed(progress);
263	    this.distance += worldSpeed * dt;
264	
265	    this.scrollParallax(worldSpeed, dt);
266	    this.spawner.update(this.distance, worldSpeed, progress);
267	    this.updateFinishLine(worldSpeed);
268	
269	    // Drive hero animation/armor timing off the SCENE clock so it freezes exactly
270	    // with the pause overlay (this.time.paused) and resumes bit-for-bit.
271	    const now = this.time.now;
272	    this.hero.tick(now);
273	    this.updateScore();
274	    this.syncHp();
275	    this.events.emit(GameEvents.progress, progress);
276	    this.emitArmor(now);
277	
278	    // Deterministic Victory: the finish line has reached the hero.
279	    if (this.finishSpawned && this.finishLine.active && this.finishLine.x <= HERO_X) {
280	      this.endRun('win');
281	    }
282	  }
