284	  private scrollParallax(worldSpeed: number, dt: number): void {
285	    this.bgFar.tilePositionX += worldSpeed * PARALLAX_FACTOR_FAR * dt;
286	    this.bgNear.tilePositionX += worldSpeed * PARALLAX_FACTOR_NEAR * dt;
287	    this.groundTile.tilePositionX += worldSpeed * PARALLAX_FACTOR_GROUND * dt;
288	    this.fgGrass.tilePositionX += worldSpeed * PARALLAX_FACTOR_GRASS * dt;
289	  }
290	
291	  private updateFinishLine(worldSpeed: number): void {
292	    if (!this.finishSpawned) {
293	      if (this.distance >= LEVEL_LENGTH - this.approach) {
294	        this.finishLine.spawn(this.spawnX, GROUND_TOP_Y);
295	        this.finishSpawned = true;
296	        this.spawner.stopSpawning(); // nothing spawns past the finish (§3.9)
297	      }
298	      return;
299	    }
300	    if (this.finishLine.active) this.finishLine.setVelocityX(-worldSpeed);
301	  }
302	
303	  // ── HUD event emitters (view-agnostic; the Hud subscribes) ─────────────────
304	  private updateScore(): void {
305	    const survival = Math.floor((this.elapsedMs / 1000) * SCORE_SURVIVAL_PER_S);
306	    this.score = this.tabletScore + survival;
307	    if (this.score !== this.lastScore) {
308	      this.events.emit(GameEvents.score, this.score);
309	      this.lastScore = this.score;
310	    }
311	  }
312	
313	  private syncHp(): void {
314	    const hp = this.hero.hp;
315	    if (hp !== this.lastHp) {
316	      this.events.emit(GameEvents.hp, hp);
317	      this.lastHp = hp;
318	    }
319	  }
